import java.io.*;
import java.util.*;

public class Main {

    static class Node {
        int key, height;
        Node left, right;
        Node(int k) { key = k; height = 1; }
    }

    static int h(Node n) { return n == null ? 0 : n.height; }

    static void update(Node n) {
        if (n != null) {
            n.height = 1 + Math.max(h(n.left), h(n.right));
        }
    }

    static int bal(Node n) { return n == null ? 0 : h(n.left) - h(n.right); }

    static Node rotateRight(Node y) {
        Node x = y.left;
        Node t = x.right;
        x.right = y;
        y.left = t;
        update(y);
        update(x);
        return x;
    }

    static Node rotateLeft(Node x) {
        Node y = x.right;
        Node t = y.left;
        y.left = x;
        x.right = t;
        update(x);
        update(y);
        return y;
    }

    static Node balance(Node n) {
        if (n == null) return null;
        update(n);
        int b = bal(n);
        if (b > 1) {
            if (bal(n.left) < 0) {
                n.left = rotateLeft(n.left);
            }
            return rotateRight(n);
        }
        if (b < -1) {
            if (bal(n.right) > 0) {
                n.right = rotateRight(n.right);
            }
            return rotateLeft(n);
        }
        return n;
    }

    static Node insert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.key) {
            n.left = insert(n.left, key);
        } else if (key > n.key) {
            n.right = insert(n.right, key);
        } else {
            // duplicate: ignore or handle as needed; assume duplicates not present or ignored
            return n;
        }
        return balance(n);
    }

    static Node minNode(Node n) {
        Node cur = n;
        while (cur.left != null) cur = cur.left;
        return cur;
    }

    static Node deleteNode(Node n, int key) {
        if (n == null) return null;

        if (key < n.key) {
            n.left = deleteNode(n.left, key);
        } else if (key > n.key) {
            n.right = deleteNode(n.right, key);
        } else {
            // node with only one child or no child
            if (n.left == null) {
                return n.right;
            } else if (n.right == null) {
                return n.left;
            }
            // node with two children: replace with in-order successor
            Node succ = minNode(n.right);
            n.key = succ.key;
            n.right = deleteNode(n.right, succ.key);
        }
        return balance(n);
    }

    static void inorder(Node n, List<Integer> list) {
        if (n == null) return;
        inorder(n.left, list);
        list.add(n.key);
        inorder(n.right, list);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        int N = Integer.parseInt(line.trim());
        int[] arr = new int[N];
        if (N > 0) {
            line = br.readLine();
            if (line != null) {
                String[] parts = line.trim().split("\\s+");
                for (int i = 0; i < N && i < parts.length; i++) {
                    arr[i] = Integer.parseInt(parts[i]);
                }
            }
        }
        Node root = null;
        for (int i = 0; i < N; i++) {
            root = insert(root, arr[i]);
        }
        int K = Integer.parseInt(br.readLine().trim());
        root = deleteNode(root, K);
        List<Integer> res = new ArrayList<>();
        inorder(root, res);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.size(); i++) {
            if (i > 0) sb.append(" ");
            sb.append(res.get(i));
        }
        // trailing space as per sample output
        if (res.size() > 0) sb.append(" ");
        System.out.println(sb.toString());
    }
}
